import { notFound, redirect } from "next/navigation"
import fs from "node:fs"
import path from "node:path"
import { auth } from "@/lib/auth"
import { isAdmin } from "@/lib/admin"
import { RecoilReportFromData, type RecoilReportRaw } from "@/document/screens/RecoilReport"
import ReportActions from "./ReportActions"
import { publicShare, applyPublicShare } from "@/lib/recoilPublicShare"

// Dynamic Recoil Report — renders a report generated by the /recoil-report
// skill (see runtime/specs/recoil-modes-v1.md). Reports are written to
// runtime/recoil/generated/<reportId>.json by the skill, committed alongside
// the page, then this route renders them through the same canonical document
// kit as the static RECOIL_SAMPLE demo at /recoil.
export const dynamic = "force-dynamic"

function externalTwin(reportId: string): string | null {
  const safe = reportId.replace(/[^a-zA-Z0-9_-]/g, "")
  const rel = `/recoil-ext/${safe}.html`
  return fs.existsSync(path.join(process.cwd(), "public", rel)) ? rel : null
}

function loadReport(reportId: string): RecoilReportRaw | null {
  const safe = reportId.replace(/[^a-zA-Z0-9_-]/g, "")
  const file = path.join(process.cwd(), "runtime", "recoil", "generated", `${safe}.json`)
  if (!fs.existsSync(file)) return null
  try {
    const raw = JSON.parse(fs.readFileSync(file, "utf-8")) as RecoilReportRaw
    // Strip passcodes server-side: the renderer is a client component, so
    // anything passed to it is serialized into the page payload.
    const meta = raw.meta
    if (meta && typeof meta === "object" && !Array.isArray(meta) && "gate" in meta) {
      const { gate: _gate, ...rest } = meta as Record<string, unknown>
      void _gate
      return { ...raw, meta: rest }
    }
    return raw
  } catch {
    return null
  }
}

export default async function DynamicRecoilReportPage({
  params,
  searchParams,
}: {
  params: Promise<{ reportId: string }>
  searchParams: Promise<{ view?: string }>
}) {
  // ADR-001 doctrine: prod enforces session, dev passes through (matches the
  // soft-auth pattern on all /api routes; also enables local visual QA of
  // generated reports without a magic-link session). Fail-closed: unset, test,
  // preview and staging all gate (matches /warroom).
  const { reportId } = await params
  const dev = process.env.NODE_ENV === "development"
  const session = dev ? null : await auth()
  const admin = dev || isAdmin(session)
  // A report on runtime/recoil/public-shares.json opens without sign-in, with its
  // listed lines stripped here, server-side (Zach's go per entry). Admins see the
  // full report; dev can preview the public view with ?view=public.
  const share = publicShare(reportId)
  const isPublicView = !!share && (!admin || (dev && (await searchParams).view === "public"))
  if (!admin && !share) {
    // A war-room link sent to a counterpart opens its counterpart-safe twin
    // (built by scripts/recoil_ext_build.sh, audience:"both" content only).
    // Reports without a twin keep the sign-in gate.
    const ext = externalTwin(reportId)
    if (ext) redirect(ext)
    if (!session?.user?.email) redirect("/compass?next=/recoil/" + reportId)
    notFound()
  }

  const full = loadReport(reportId)
  if (!full) notFound()
  const data = isPublicView && share ? applyPublicShare(full, share) : full

  return (
    <div style={{ background: "#020408", minHeight: "100vh", padding: "40px 0" }}>
      <div style={{ maxWidth: 760, margin: "0 auto", padding: "0 20px" }}>
        {!isPublicView && <ReportActions sharePath={share ? `/recoil/${reportId}` : externalTwin(reportId)} />}
        <RecoilReportFromData data={data} />
      </div>
    </div>
  )
}
